import React, { useState, useRef } from "react";
import { X, Plus, Minus, Check, ArrowLeft } from "lucide-react";
import JewelArt from "./JewelArt";
import { COLORS, FONT_DISPLAY } from "../constants/theme";
import { money } from "../utils/helpers";

const STEP = {
  CART: "cart",
  PHONE: "phone",
  OTP: "otp",
};

export default function CartDrawer({
  cartOpen,
  setCartOpen,
  cart,
  checkedOut,
  setCheckedOut,
  updateQty,
  removeItem,
  subtotal,
}) {
  const [step, setStep] = useState(STEP.CART);
  const [phone, setPhone] = useState("");
  const [otp, setOtp] = useState(["", "", "", "", "", ""]);
  const otpRefs = useRef([]);

  const resetCheckoutFlow = () => {
    setStep(STEP.CART);
    setPhone("");
    setOtp(["", "", "", "", "", ""]);
  };

  const handleClose = () => {
    setCartOpen(false);
    // give the drawer time to slide out before resetting the view
    setTimeout(() => {
      if (!checkedOut) resetCheckoutFlow();
    }, 350);
  };

  const handleOtpChange = (index, value) => {
    if (!/^[0-9]?$/.test(value)) return;
    const next = [...otp];
    next[index] = value;
    setOtp(next);
    if (value && index < otp.length - 1) {
      otpRefs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index, e) => {
    if (e.key === "Backspace" && !otp[index] && index > 0) {
      otpRefs.current[index - 1]?.focus();
    }
  };

  const phoneValid = phone.replace(/\D/g, "").length >= 10;
  const otpValid = otp.every((d) => d !== "");

  const handleVerify = () => {
    if (!otpValid) return;
    setCheckedOut(true);
    setStep(STEP.CART);
  };

  const inputStyle = {
    width: "100%",
    background: COLORS.surfaceSoft,
    border: `1px solid ${COLORS.border}`,
    color: COLORS.text,
    fontSize: 15,
    padding: "13px 14px",
    outline: "none",
    fontFamily: "inherit",
  };

  const primaryButtonStyle = (disabled) => ({
    width: "100%",
    background: disabled ? COLORS.surfaceMuted : COLORS.surfaceStrong,
    color: disabled ? COLORS.textFaint : COLORS.textOnStrong,
    border: "none",
    padding: "15px 0",
    fontSize: 14,
    letterSpacing: "0.03em",
    cursor: disabled ? "not-allowed" : "pointer",
  });

  const backButtonStyle = {
    display: "flex",
    alignItems: "center",
    gap: 6,
    background: "none",
    border: "none",
    color: COLORS.textMuted,
    fontSize: 13,
    padding: 0,
    cursor: "pointer",
  };

  const renderHeaderTitle = () => {
    if (step === STEP.PHONE) return "Enter phone number";
    if (step === STEP.OTP) return "Verify OTP";
    return "Your bag";
  };

  return (
    <>
      <div
        onClick={handleClose}
        style={{
          position: "fixed",
          inset: 0,
          background: COLORS.overlay,
          opacity: cartOpen ? 1 : 0,
          pointerEvents: cartOpen ? "auto" : "none",
          transition: "opacity 0.3s ease",
          zIndex: 60,
        }}
      />
      <aside
        style={{
          position: "fixed",
          top: 0,
          right: 0,
          bottom: 0,
          width: "min(420px, 100vw)",
          background: COLORS.surfaceCard,
          zIndex: 61,
          transform: cartOpen ? "translateX(0)" : "translateX(100%)",
          transition: "transform 0.35s ease",
          display: "flex",
          flexDirection: "column",
        }}
      >
        <div
          className="flex items-center justify-between"
          style={{ padding: "20px 22px", borderBottom: `1px solid ${COLORS.border}` }}
        >
          <div className="flex items-center" style={{ gap: 12 }}>
            {(step === STEP.PHONE || step === STEP.OTP) && (
              <button
                onClick={() => setStep(step === STEP.OTP ? STEP.PHONE : STEP.CART)}
                style={{ background: "none", border: "none", color: COLORS.text, display: "flex" }}
                aria-label="Go back"
              >
                <ArrowLeft size={18} />
              </button>
            )}
            <h3 style={{ fontFamily: FONT_DISPLAY, fontSize: 20 }}>{renderHeaderTitle()}</h3>
          </div>
          <button onClick={handleClose} style={{ background: "none", border: "none", color: COLORS.text }} aria-label="Close cart">
            <X size={20} />
          </button>
        </div>

        <div style={{ flex: 1, overflowY: "auto", padding: "10px 22px" }}>
          {checkedOut ? (
            <div style={{ textAlign: "center", padding: "60px 10px" }}>
              <Check size={30} color={COLORS.verdigris} style={{ marginBottom: 14 }} />
              <p style={{ fontFamily: FONT_DISPLAY, fontSize: 20, marginBottom: 8 }}>Order placed</p>
              <p style={{ fontSize: 14, color: COLORS.textMuted }}>
                A confirmation is on its way to your inbox. Thank you for choosing reclaimed gold.
              </p>
            </div>
          ) : step === STEP.PHONE ? (
            <div style={{ padding: "24px 0" }}>
              <p style={{ fontSize: 13, color: COLORS.textSoft, marginBottom: 18 }}>
                We'll text you a one-time code to confirm your order.
              </p>
              <label style={{ fontSize: 12, color: COLORS.textMuted, display: "block", marginBottom: 8 }}>
                Phone number
              </label>
              <div className="flex items-center" style={{ border: `1px solid ${COLORS.border}`, background: COLORS.surfaceSoft }}>
                <span style={{ padding: "13px 12px", fontSize: 15, color: COLORS.textMuted, borderRight: `1px solid ${COLORS.border}` }}>
                  +91
                </span>
                <input
                  type="tel"
                  inputMode="numeric"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value.replace(/[^\d\s]/g, ""))}
                  placeholder="98765 43210"
                  style={{ ...inputStyle, border: "none", background: "transparent" }}
                  autoFocus
                />
              </div>
            </div>
          ) : step === STEP.OTP ? (
            <div style={{ padding: "24px 0" }}>
              <p style={{ fontSize: 13, color: COLORS.textSoft, marginBottom: 4 }}>
                Enter the 6-digit code sent to
              </p>
              <p style={{ fontSize: 14, color: COLORS.text, marginBottom: 22 }}>+91 {phone}</p>
              <div className="flex items-center justify-between" style={{ gap: 8 }}>
                {otp.map((digit, i) => (
                  <input
                    key={i}
                    ref={(el) => (otpRefs.current[i] = el)}
                    type="text"
                    inputMode="numeric"
                    maxLength={1}
                    value={digit}
                    onChange={(e) => handleOtpChange(i, e.target.value)}
                    onKeyDown={(e) => handleOtpKeyDown(i, e)}
                    style={{
                      width: 44,
                      height: 52,
                      textAlign: "center",
                      fontSize: 18,
                      background: COLORS.surfaceSoft,
                      border: `1px solid ${digit ? COLORS.verdigris : COLORS.border}`,
                      color: COLORS.text,
                      outline: "none",
                    }}
                    autoFocus={i === 0}
                  />
                ))}
              </div>
              <button
                onClick={() => {/* resend logic */}}
                style={{ background: "none", border: "none", color: COLORS.verdigris, fontSize: 12.5, padding: 0, marginTop: 18, cursor: "pointer" }}
              >
                Resend code
              </button>
            </div>
          ) : cart.length === 0 ? (
            <div style={{ textAlign: "center", padding: "60px 10px" }}>
              <p style={{ fontSize: 14, color: COLORS.textSoft }}>Your bag is empty - for now.</p>
            </div>
          ) : (
            cart.map((item) => (
              <div key={item.id} className="flex" style={{ gap: 14, padding: "16px 0", borderBottom: `1px solid ${COLORS.border}` }}>
                <div style={{ width: 64, height: 64, background: COLORS.surfaceSoft, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <JewelArt type={item.art} style={{ width: "60%", color: COLORS.verdigris }} />
                </div>
                <div style={{ flex: 1 }}>
                  <div className="flex items-start justify-between">
                    <div>
                      <p style={{ fontFamily: FONT_DISPLAY, fontSize: 15 }}>{item.name}</p>
                      <p style={{ fontSize: 12, color: COLORS.textSoft }}>{item.material}</p>
                    </div>
                    <button onClick={() => removeItem(item.id)} style={{ background: "none", border: "none", color: COLORS.textFaint }} aria-label={`Remove ${item.name}`}>
                      <X size={15} />
                    </button>
                  </div>
                  <div className="flex items-center justify-between" style={{ marginTop: 10 }}>
                    <div className="flex items-center" style={{ border: `1px solid ${COLORS.border}`, gap: 0 }}>
                      <button onClick={() => updateQty(item.id, -1)} style={{ background: "none", border: "none", padding: "4px 8px", color: COLORS.text }} aria-label="Decrease quantity">
                        <Minus size={12} />
                      </button>
                      <span style={{ fontSize: 13, minWidth: 18, textAlign: "center" }}>{item.qty}</span>
                      <button onClick={() => updateQty(item.id, 1)} style={{ background: "none", border: "none", padding: "4px 8px", color: COLORS.text }} aria-label="Increase quantity">
                        <Plus size={12} />
                      </button>
                    </div>
                    <span style={{ fontSize: 14 }}>{money(item.price * item.qty)}</span>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        {!checkedOut && step === STEP.CART && cart.length > 0 && (
          <div style={{ padding: "20px 22px", borderTop: `1px solid ${COLORS.border}` }}>
            <div className="flex items-center justify-between" style={{ marginBottom: 16 }}>
              <span style={{ fontSize: 14, color: COLORS.textMuted }}>Subtotal</span>
              <span style={{ fontFamily: FONT_DISPLAY, fontSize: 20 }}>{money(subtotal)}</span>
            </div>
            <button onClick={() => setStep(STEP.PHONE)} style={primaryButtonStyle(false)}>
              Checkout
            </button>
            <p style={{ fontSize: 11.5, color: COLORS.textFaint, marginTop: 10, textAlign: "center" }}>
              Shipping and duties calculated at checkout.
            </p>
          </div>
        )}

        {!checkedOut && step === STEP.PHONE && (
          <div style={{ padding: "20px 22px", borderTop: `1px solid ${COLORS.border}` }}>
            <button onClick={() => setStep(STEP.OTP)} disabled={!phoneValid} style={primaryButtonStyle(!phoneValid)}>
              Send OTP
            </button>
          </div>
        )}

        {!checkedOut && step === STEP.OTP && (
          <div style={{ padding: "20px 22px", borderTop: `1px solid ${COLORS.border}` }}>
            <button onClick={handleVerify} disabled={!otpValid} style={primaryButtonStyle(!otpValid)}>
              Verify & place order
            </button>
          </div>
        )}
      </aside>
    </>
  );
}
